 "content": "from collections import Counter


def _rectangular_frames(grid):
    """Return bounding boxes for fully closed, single-color rectangular outlines."""
    h, w = len(grid), len(grid[0])
    frames = []
    colors = {v for row in grid for v in row if v != 0}
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not cells:
            continue
        r0 = min(r for r, _ in cells)
        r1 = max(r for r, _ in cells)
        c0 = min(c for _, c in cells)
        c1 = max(c for _, c in cells)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        perimeter = {(r, c) for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)
                     if r in (r0, r1) or c in (c0, c1)}
        if all(grid[r][c] == color for r, c in perimeter):
            # The outline must contain exactly this color on its perimeter;
            # other same-colored isolated cells would otherwise expand its box.
            frames.append((r0, r1, c0, c1, color))
    # Different colors cannot define overlapping boxes in these tasks; sort for stable handling.
    return frames


def transform(grid):
    out = [row[:] for row in grid]
    frames = _rectangular_frames(grid)
    if not frames:
        return out

    def in_frame_border(r, c):
        return any(r0 <= r <= r1 and c0 <= c <= c1 and
                   (r in (r0, r1) or c in (c0, c1))
                   for r0, r1, c0, c1, _ in frames)

    # Isolated colored specks encode the fill color by their frequency.
    speck_counts = Counter(grid[r][c] for r in range(len(grid)) for c in range(len(grid[0]))
                           if grid[r][c] != 0 and not in_frame_border(r, c))
    # Erase the encoding specks; the outlined frames are retained.
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if not in_frame_border(r, c):
                out[r][c] = 0

    for r0, r1, c0, c1, _border_color in frames:
        ir0, ir1, ic0, ic1 = r0 + 1, r1 - 1, c0 + 1, c1 - 1
        needed = sum(1 for r in range(ir0, ir1 + 1) for c in range(ic0, ic1 + 1)
                    if ((r - ir0) + (c - ic0)) % 2 == 0)
        matches = [color for color, count in speck_counts.items() if count == needed]
        if len(matches) == 1:
            fill = matches[0]
            for r in range(ir0, ir1 + 1):
                for c in range(ic0, ic1 + 1):
                    if ((r - ir0) + (c - ic0)) % 2 == 0:
                        out[r][c] = fill
    return out
